// spec: specs/monitoring.md (2.1, 2.2) · case: .qa/tests/monitoring/MON-009.md
// ОБЯЗАТЕЛЬНО — регресс приложения (#3bf9dd7f); ручной кейс для приложения — MON-APP-3bf9dd7f.md
// seed: tests/seed.user.spec.ts (сессия user.json — из профиля Mac devA, без нового входа: лимит устройств 2/2)
// Открываем /monitor напрямую (только веб): на «בית» может висеть окно тревоги с другого телефона аккаунта.
// Окно тревоги и «ראיתי, אני בדרך» не трогаем.
import { test, expect, type Page } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

const STAY_ON = 'הטלפון יישאר דלוק';
const FAIL_LINE = 'לא הצלחנו להשאיר את המסך דלוק. הקישו כאן כדי לנסות שוב.';

const visible = (page: Page, text: string | RegExp) => page.getByText(text).filter({ visible: true });
const btn = (page: Page, name: string) => page.getByRole('button', { name, exact: true }).filter({ visible: true });

/** Имитация Safari без жеста (только веб): navigator.wakeLock.request отклоняется NotAllowedError, пока не выставлен window.__wl.ok. */
async function mockWakeLock(page: Page) {
  await page.addInitScript(() => {
    const st = ((window as any).__wl = { calls: 0, ok: false });
    const wakeLock = {
      request: async (type: string) => {
        st.calls++;
        if (st.ok) return { released: false, type, release: async () => {}, addEventListener() {}, removeEventListener() {}, onrelease: null };
        throw new DOMException('The request is not allowed by the user agent.', 'NotAllowedError');
      },
    };
    Object.defineProperty(navigator, 'wakeLock', { configurable: true, get: () => wakeLock });
  });
}
const wlCalls = (page: Page) => page.evaluate(() => (window as any).__wl.calls as number);

async function openSafetyCheck(page: Page) {
  await page.goto('/monitor?mock=calm');
  await expect(visible(page, 'שלב 1 מתוך 3')).toBeVisible();
  await expect(visible(page, 'בדיקת בטיחות')).toBeVisible();
  await expect(visible(page, /2 מתוך 5/)).toBeVisible(); // проверка завершилась
}

async function confirmSound(page: Page) {
  await page.getByRole('button', { name: /עוצמת צפצוף מקסימלית/ }).filter({ visible: true }).click();
  await btn(page, 'השמעה').click();
  await btn(page, 'שמעתי').click();
  await expect(visible(page, /3 מתוך 5/)).toBeVisible();
}

test.describe('Проверка безопасности — удержание экрана (wake lock)', () => {
  test('При открытии нет строки «הטלפון יישאר דלוק», после звука «המשך» активна и ведёт на шаг 2 #3bf9dd7f @iphone @prod-safe', async ({ page }) => {
    // 1–2. Открыть проверку безопасности (и повторно — ещё 2 раза, как в ручной проверке)
    for (let i = 0; i < 3; i++) {
      await openSafetyCheck(page);
      // Ожидаемо: строки про удержание экрана нет (источник: «מה רצוי» #3bf9dd7f)
      await expect(visible(page, STAY_ON)).toHaveCount(0);
      await expect(visible(page, /לא הצלחנו להשאיר את המסך דלוק/)).toHaveCount(0);
    }
    // 3. Звук: «עוצמת צפצוף מקסימלית» → «השמעה» → «שמעתי» → «3 מתוך 5»
    await confirmSound(page);
    await expect(visible(page, STAY_ON)).toHaveCount(0);
    // 4. «המשך» не заблокирована → шаг 2
    const next = btn(page, 'המשך');
    await expect(next).not.toHaveAttribute('aria-disabled', 'true');
    await next.click();
    await expect(page).toHaveURL(/\/monitor\/camera/);
    await expect(visible(page, 'שלב 2 מתוך 3')).toBeVisible();
    await expect(visible(page, 'כוונו את המצלמה לבריכה')).toBeVisible();
  });

  test('Отказ wake lock: при открытии строки нет; после «בדיקה חוזרת» — «הקישו כאן כדי לנסות שוב», нажатие повторяет попытку и убирает строку #3bf9dd7f @iphone @prod-safe', async ({ page }) => {
    await mockWakeLock(page);
    // 1. Открыть — запрос без жеста отклонён, но это не сбой: строки нет
    await openSafetyCheck(page);
    await expect(visible(page, STAY_ON)).toHaveCount(0);
    await expect(visible(page, /לא הצלחנו להשאיר את המסך דלוק/)).toHaveCount(0);
    await confirmSound(page);
    await expect(visible(page, STAY_ON)).toHaveCount(0);
    await expect(btn(page, 'המשך')).not.toHaveAttribute('aria-disabled', 'true');

    // 2. «בדיקה חוזרת» — запрос по нажатию, он снова отклонён → строка с предложением повторить
    const before = await wlCalls(page);
    await btn(page, 'בדיקה חוזרת').click();
    await expect(visible(page, FAIL_LINE)).toBeVisible();
    await expect(visible(page, STAY_ON)).toBeVisible();
    expect(await wlCalls(page), 'запрос wake lock отправлен по нажатию «בדיקה חוזרת»').toBeGreaterThan(before);
    // При предупреждающей строке «המשך» серая (решение 2026-10-08, D-20 / Figma 07.2)
    await expect(btn(page, 'המשך')).toHaveAttribute('aria-disabled', 'true');

    // 3. Удержание экрана снова доступно → нажать строку → повторная попытка, строка пропадает
    await page.evaluate(() => ((window as any).__wl.ok = true));
    const beforeRetry = await wlCalls(page);
    await visible(page, FAIL_LINE).click();
    await expect(visible(page, FAIL_LINE)).toHaveCount(0);
    await expect(visible(page, STAY_ON)).toHaveCount(0);
    expect(await wlCalls(page), 'нажатие строки повторяет запрос wake lock').toBeGreaterThan(beforeRetry);
    await expect(visible(page, /3 מתוך 5/)).toBeVisible();
    await expect(btn(page, 'המשך')).not.toHaveAttribute('aria-disabled', 'true');
  });
});
